  -map "[a]" -t 120 -c:a aac -b:a 160k "${work_dir}/audio.m4a"

ffmpeg -hide_banner -loglevel error -y -i "${work_dir}/video.mp4" -i "${work_dir}/audio.m4a" -map 0:v -map 1:a -c:v copy -c:a copy -t 120 -movflags +faststart "${output}"
